{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.bill import per_person"
  ],
  "tests": [
    {
      "name": "test_per_person_rounds_up_to_avoid_shortfall",
      "intent": "three people splitting 100.00 each pay 33.34 so the total is 100.02",
      "code": "# intent: three people splitting 100.00 each pay 33.34 so the total is 100.02\ndef test_per_person_rounds_up_to_avoid_shortfall():\n    assert per_person(Decimal(\"100.00\"), 3) == Decimal(\"33.34\")\n"
    },
    {
      "name": "test_per_person_exact_split_no_rounding",
      "intent": "when the amount divides evenly, no rounding is needed",
      "code": "# intent: when the amount divides evenly, no rounding is needed\ndef test_per_person_exact_split_no_rounding():\n    assert per_person(Decimal(\"90.00\"), 3) == Decimal(\"30.00\")\n"
    },
    {
      "name": "test_per_person_with_tip_rounds_up",
      "intent": "tip is included and the result is rounded up to the next cent",
      "code": "# intent: tip is included and the result is rounded up to the next cent\ndef test_per_person_with_tip_rounds_up():\n    assert per_person(Decimal(\"100.00\"), 2, Decimal(\"10\")) == Decimal(\"55.00\")\n"
    },
    {
      "name": "test_per_person_zero_people_raises_value_error",
      "intent": "zero people is invalid and raises ValueError",
      "code": "# intent: zero people is invalid and raises ValueError\ndef test_per_person_zero_people_raises_value_error():\n    with pytest.raises(ValueError):\n        per_person(Decimal(\"90.00\"), 0)\n"
    },
    {
      "name": "test_per_person_negative_people_raises_value_error",
      "intent": "negative number of people is invalid and raises ValueError",
      "code": "# intent: negative number of people is invalid and raises ValueError\ndef test_per_person_negative_people_raises_value_error():\n    with pytest.raises(ValueError):\n        per_person(Decimal(\"90.00\"), -1)\n"
    },
    {
      "name": "test_per_person_one_cent_rounding_boundary",
      "intent": "a total that is one cent over a multiple of people rounds up to the next cent",
      "code": "# intent: a total that is one cent over a multiple of people rounds up to the next cent\ndef test_per_person_one_cent_rounding_boundary():\n    assert per_person(Decimal(\"0.01\"), 2) == Decimal(\"0.01\")\n"
    }
  ]
}
